Extensions.ExtractScript:
param([xml]$Document)
foreach($file in $Document.unattend.Extensions.File){
    $path=[System.Environment]::ExpandEnvironmentVariables($file.GetAttribute('path'));
    $dir=[System.IO.Path]::GetDirectoryName($path);
    if(!(Test-Path $dir)){New-Item -ItemType Directory -Path $dir -Force | Out-Null;}
    [System.IO.File]::WriteAllText($path,$file.InnerText.TrimEnd());
}

Extensions.File:
# Tweaks.ps1  (runs during specialize)
Write-Host "== Tweaks Script Starting ==";

# ---------- 1. Debloat consumer apps ----------
$apps = @(
  "Microsoft.BingNews","Microsoft.GetHelp","Microsoft.Getstarted","Microsoft.People",
  "Microsoft.WindowsAlarms","Microsoft.WindowsFeedbackHub","Microsoft.WindowsMaps",
  "Microsoft.XboxGamingOverlay","Microsoft.YourPhone","Microsoft.ZuneMusic",
  "Microsoft.ZuneVideo","Microsoft.BingWeather","Microsoft.MicrosoftOfficeHub",
  "Microsoft.OneConnect","Microsoft.SkypeApp","Microsoft.Todos","Microsoft.Whiteboard"
);
foreach($app in $apps){
    Write-Host "Removing $app";
    Get-AppxProvisionedPackage -Online | Where DisplayName -Like $app | Remove-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue;
    Get-AppxPackage -AllUsers | Where Name -Like $app | Remove-AppxPackage -AllUsers -ErrorAction SilentlyContinue;
}

# ---------- 2. Disable consumer experience / tips ----------
$cdm="HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\ContentDeliveryManager";
if(Test-Path $cdm){
    $keys=@(
      "SubscribedContent-338388Enabled","SubscribedContent-353694Enabled","SubscribedContent-310093Enabled",
      "SubscribedContent-338387Enabled","SilentInstalledAppsEnabled","SystemPaneSuggestionsEnabled"
    );
    foreach($k in $keys){Set-ItemProperty -Path $cdm -Name $k -Value 0 -ErrorAction SilentlyContinue;}
}

# ---------- 3. Minimise telemetry ----------
New-Item -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" -Force | Out-Null;
Set-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" -Name "AllowTelemetry" -Type DWord -Value 0;

# ---------- 4. Disable background apps ----------
New-Item -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\System" -Force | Out-Null;
Set-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\System" -Name "AllowBackgroundAppsGlobal" -Type DWord -Value 2;

# ---------- 5. Disable hibernation ----------
powercfg.exe /hibernate off

# ---------- 6. Create & set High Performance power plan ----------
$hpGuid = "8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c";  # built‑in High performance
powercfg.exe /setactive $hpGuid

# ---------- 7. Enable Storage Sense & weekly cleanup ----------
New-Item -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\StorageSense\Parameters\StoragePolicy" -Force | Out-Null;
Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\StorageSense\Parameters\StoragePolicy" -Name "01" -Type DWord -Value 1;  # Storage Sense On
# schedule weekly cleanup via Task Scheduler
schtasks.exe /Create /TN "WeeklyDiskCleanup" /SC WEEKLY /D SUN /RL HIGHEST /RU SYSTEM /TR "cleanmgr.exe /sagerun:1" /F

# ---------- 8. Enable Memory Integrity (requires reboot capable hardware) ----------
New-Item -Path "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\MemoryIntegrity" -Force | Out-Null;
Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\MemoryIntegrity" -Name "Enabled" -Type DWord -Value 1;

# ---------- 9. Clean Start‑menu pinned apps (default user + current) ----------
$pinnedJson = '{ "pinnedList": [] }';
$defaultShell = "C:\Users\Default\AppData\Local\Microsoft\Windows\Shell";
New-Item -Path $defaultShell -ItemType Directory -Force | Out-Null;
$pinnedPathDefault = Join-Path $defaultShell "LayoutModification.json";
Set-Content -Path $pinnedPathDefault -Value $pinnedJson -Encoding UTF8;

$currentShell = "$env:LOCALAPPDATA\Microsoft\Windows\Shell";
New-Item -Path $currentShell -ItemType Directory -Force | Out-Null;
Set-Content -Path (Join-Path $currentShell "LayoutModification.json") -Value $pinnedJson -Encoding UTF8;

# ---------- 10. Restore restricted execution policy ----------
Set-ExecutionPolicy Restricted -Scope LocalMachine -Force;

Write-Host "== Tweaks Complete ==";
